using System;using System.Reflection;using UnityEngine;
public static class ValidateRainErosion {
 public static object Main(){if(!Application.isPlaying)throw new Exception("Requires Play Mode");var erosion=Array.Find(UnityEngine.Object.FindObjectsByType<RainRoadErosion>(),e=>e.transform.position.z==30);var ground=erosion.GetComponent<SoftGroundRuts>();var road=erosion.GetComponent<RainSoakedRoad>();var field=typeof(ForestDayNightWeather).GetField("rain",BindingFlags.NonPublic|BindingFlags.Instance);float rain=(float)field.GetValue(road.weather);try{field.SetValue(road.weather,0f);float before=ground.DepthAt(erosion.runoffPoints[10]);erosion.Advance(60);float dryChange=ground.DepthAt(erosion.runoffPoints[10])-before;field.SetValue(road.weather,1f);road.Advance(100);for(int i=0;i<120;i++)erosion.Advance(.5f);ground.Commit();float wetDepth=ground.DepthAt(erosion.runoffPoints[10]);var probe=new GameObject("Independent erosion mesh probe");probe.transform.SetPositionAndRotation(ground.transform.position,ground.transform.rotation);var visible=probe.AddComponent<MeshCollider>();visible.sharedMesh=ground.GetComponent<MeshFilter>().sharedMesh;int rays=0;float error=0;try{foreach(var point in erosion.runoffPoints){var ray=new Ray(point+Vector3.up,Vector3.down);if(!visible.Raycast(ray,out var a,2)||!ground.GetComponent<MeshCollider>().Raycast(ray,out var b,2))throw new Exception("Missing erosion surface");error=Mathf.Max(error,Mathf.Abs(a.point.y-b.point.y));rays++;}}finally{UnityEngine.Object.DestroyImmediate(probe);}if(dryChange>.0001f||wetDepth<.055f||error>.002f)throw new Exception("Erosion failed");return new{success=true,dryChange,downpourSeconds=60,washedDepth=wetDepth,independentRays=rays,visibleCollisionError=error};}finally{field.SetValue(road.weather,rain);}}
}
